        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    groups = []
    for r in active:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)
    if len(groups) < 2:
        return out
    upper, lower = groups[0], groups[-1]
    for ru, rl in zip(upper, lower):
        for c in range(min(len(grid[ru]), len(grid[rl]))):
            if grid[ru][c] != grid[rl][c]:
                out[ru][c] = 1
    return out
