        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)
    if len(groups) < 2:
        return out
    upper, lower = groups[0], groups[-1]
    # The two separated motifs are aligned; extend the shorter copy by
    # highlighting its missing cells wherever the longer copy has foreground.
    for upper_row, lower_row in zip(upper, lower):
        width = min(len(grid[upper_row]), len(grid[lower_row]))
        for c in range(width):
            upper_fg = grid[upper_row][c] != background
            lower_fg = grid[lower_row][c] != background
            if upper_fg and not lower_fg:
                out[lower_row][c] = 1
            elif lower_fg and not upper_fg:
                out[upper_row][c] = 1
    return out
