    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    groups = []
    for r in active:
        if not groups or r > groups[-1][-1] + 1:
            groups.append([r])
        else:
            groups[-1].append(r)
    if len(groups) < 2:
        return out
    upper, lower = groups[0], groups[-1]

    # The two printed rows are the same pattern at slightly different horizontal
    # positions; determine shift by the greatest count of aligned foregrounds.
    w = len(grid[0])
    candidates = range(-w + 1, w)
    def score(shift):
        matches = total = 0
        for ru, rl in zip(upper, lower):
            for c in range(w):
                j = c + shift
                if 0 <= j < w:
                    total += 1
                    matches += (grid[ru][c] != bg) == (grid[rl][j] != bg)
        return (matches / total if total else -1, -abs(shift))
    shift = max(candidates, key=score)
    # Mark first-copy background cells that correspond to later-copy foreground.
    for ru, rl in zip(upper, lower):
        for c in range(w):
            j = c + shift
            if 0 <= j < w and grid[ru][c] == bg and grid[rl][j] != bg:
                out[ru][c] = 1
    return out
